-- PostgreSQL conversion of the SQL Server schema in schema.sql
-- Review access policies before exposing these tables through the Supabase Data API.

CREATE TABLE "clientes" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "nombre_cliente" varchar(255) NOT NULL,
  "telefono" varchar(50) NULL,
  "correo" varchar(255) NULL,
  PRIMARY KEY ( "id" )
);

INSERT INTO "clientes" ("nombre_cliente")
SELECT 'Consumidor final'
WHERE NOT EXISTS (SELECT 1 FROM "clientes" WHERE lower("nombre_cliente") = 'consumidor final');

CREATE TABLE "cuentas" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "marca_id" integer NULL,
  "banco" text NULL,
  "no_cuenta" text NULL,
  CONSTRAINT "pk_cuentas" PRIMARY KEY ( "id" )
);

CREATE TABLE "detalle_retiro" (
  "detalle_id" integer NOT NULL,
  "retiro_id" integer NULL,
  "producto_id" integer NULL,
  "cantidad" integer NULL,
  CONSTRAINT "pk_detalle_retiro" PRIMARY KEY ( "detalle_id" )
);

CREATE TABLE "estados" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "modulo" varchar(100) NOT NULL,
  "nombre" varchar(100) NOT NULL,
  "descripcion" text NULL,
  PRIMARY KEY ( "id" )
);

INSERT INTO "estados" ("modulo", "nombre", "descripcion")
SELECT 'ventas', 'Facturada', 'Venta emitida'
WHERE NOT EXISTS (SELECT 1 FROM "estados" WHERE lower("modulo") = 'ventas' AND lower("nombre") = 'facturada');

CREATE TABLE "ingreso_detalles" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "ingreso_id" integer NOT NULL,
  "producto_id" integer NOT NULL,
  "cantidad" integer NOT NULL,
  "precio_ingreso" numeric(12, 2) NULL,
  PRIMARY KEY ( "id" )
);

CREATE TABLE "ingresos" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "marca_id" integer NOT NULL,
  "usuario_id" integer NOT NULL,
  "tipo_carga" varchar(100) NOT NULL,
  "observaciones" text NULL,
  "estado_id" integer NOT NULL,
  "fecha_ingreso" timestamp without time zone NULL,
  PRIMARY KEY ( "id" )
);

CREATE TABLE "kardex" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "producto_id" integer NOT NULL,
  "usuario_id" integer NOT NULL,
  "tipo_movimiento" varchar(100) NOT NULL,
  "cantidad" integer NOT NULL,
  "referencia_id" integer NULL,
  "motivo" text NULL,
  "fecha" timestamp without time zone NULL,
  PRIMARY KEY ( "id" )
);

CREATE TABLE "liquidacion_detalles" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "liquidacion_id" integer NOT NULL,
  "producto_id" integer NOT NULL,
  "cantidad_vendida" integer NOT NULL,
  "monto_efectivo" numeric(12, 2) NULL,
  "monto_tarjeta" numeric(12, 2) NULL,
  "comision_pos" numeric(12, 2) NULL,
  "subtotal_neto" numeric(12, 2) NOT NULL,
  PRIMARY KEY ( "id" )
);

CREATE TABLE "liquidaciones" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "marca_id" integer NOT NULL,
  "periodo_inicio" date NOT NULL,
  "periodo_fin" date NOT NULL,
  "total_bruto" numeric(12, 2) NOT NULL,
  "total_comision_pos" numeric(12, 2) NOT NULL,
  "total_neto_pagar" numeric(12, 2) NOT NULL,
  "estado_id" integer NOT NULL,
  "pdf_url" text NULL,
  "fecha_generacion" timestamp without time zone NULL,
  PRIMARY KEY ( "id" )
);

CREATE TABLE "marcas" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "nombre_marca" varchar(255) NOT NULL,
  "contacto_nombre" varchar(255) NULL,
  "telefono" varchar(50) NULL,
  "email" varchar(255) NULL,
  "categoria" text NULL,
  "ciudad_pais" text NULL,
  "razon_social" text NULL,
  "redes_sociales" text NULL,
  "cargo" text NULL,
  "nombre_representante" text NULL,
  "tiempo_estancia" double precision NULL,
  "fecha_ingreso" timestamp without time zone NULL,
  "catalogo" text NULL,
  "estado_id" integer NOT NULL,
  "cuentas" integer NULL,
  "fecha_registro" timestamp without time zone NULL,
  "codigo" text NULL,
  "logo" text NULL,
  CONSTRAINT "pk__marcas__3213e83fb123f4e2" PRIMARY KEY ( "id" )
);

CREATE TABLE "metodo_pago" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "metodo_pago" varchar(100) NOT NULL,
  PRIMARY KEY ( "id" )
);

INSERT INTO "metodo_pago" ("metodo_pago")
SELECT seed."metodo_pago" FROM (VALUES ('Efectivo'), ('Tarjeta'), ('Transferencia')) AS seed("metodo_pago")
WHERE NOT EXISTS (SELECT 1 FROM "metodo_pago" existing WHERE lower(existing."metodo_pago") = lower(seed."metodo_pago"));

CREATE TABLE "pagos_venta" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "venta_id" integer NOT NULL,
  "metodo_pago" varchar(100) NOT NULL,
  "monto" numeric(12, 2) NOT NULL,
  "comision_porcentaje" numeric(5, 4) NULL,
  "monto_comision" numeric(12, 2) NULL,
  "fecha_pago" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ( "id" )
);

CREATE TABLE "productos" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "marca_id" integer NOT NULL,
  "codigo_qr" varchar(255) NOT NULL,
  "sku" varchar(100) NULL,
  "nombre" varchar(255) NOT NULL,
  "descripcion" text NULL,
  "precio" numeric(12, 2) NOT NULL,
  "costo_nio" numeric NULL,
  "costo_envio_nio" numeric(12, 2) NOT NULL DEFAULT 0,
  "costo_total_nio" numeric(12, 2) GENERATED ALWAYS AS (round(coalesce("costo_nio", 0) + "costo_envio_nio", 2)) STORED,
  "precio_minimo_nio" numeric(12, 2) GENERATED ALWAYS AS (round(coalesce("costo_nio", 0) + "costo_envio_nio", 2)) STORED,
  "margen_utilidad_pct" numeric(7, 2) NOT NULL DEFAULT 30,
  "utilidad_nio" numeric(12, 2) GENERATED ALWAYS AS (round((coalesce("costo_nio", 0) + "costo_envio_nio") * "margen_utilidad_pct" / 100, 2)) STORED,
  "precio_sugerido_nio" numeric(12, 2) GENERATED ALWAYS AS (round((coalesce("costo_nio", 0) + "costo_envio_nio") * (1 + "margen_utilidad_pct" / 100), 2)) STORED,
  "imagen_url" text NULL,
  "estado_id" integer NOT NULL,
  PRIMARY KEY ( "id" )
);

-- Alternate QR codes resolve to one canonical product without discarding printed labels.
CREATE TABLE IF NOT EXISTS "producto_codigos_qr" (
  "codigo_qr" varchar(255) NOT NULL,
  "producto_id" integer NOT NULL,
  PRIMARY KEY ( "codigo_qr" ),
  CONSTRAINT "fk_producto_codigos_qr_producto" FOREIGN KEY ("producto_id") REFERENCES "productos" ("id") ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS "ix_producto_codigos_qr_producto_id" ON "producto_codigos_qr" ("producto_id");
ALTER TABLE "producto_codigos_qr" ENABLE ROW LEVEL SECURITY;

-- Purchases and their product lines. Purchases update inventory balances and product acquisition costs in the API.
CREATE TABLE IF NOT EXISTS "compras" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "marca_id" integer NULL,
  "proveedor" varchar(255) NOT NULL,
  "referencia" varchar(120) NULL,
  "fecha_compra" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "costo_productos_nio" numeric(12, 2) NOT NULL DEFAULT 0,
  "costo_envio_nio" numeric(12, 2) NOT NULL DEFAULT 0,
  "total_nio" numeric(12, 2) NOT NULL DEFAULT 0,
  "pago_efectivo_nio" numeric(12, 2) NOT NULL DEFAULT 0,
  "pago_cuenta_nio" numeric(12, 2) NOT NULL DEFAULT 0,
  "observaciones" text NULL,
  PRIMARY KEY ( "id" ),
  CONSTRAINT "fk_compras_marca" FOREIGN KEY ("marca_id") REFERENCES "marcas" ("id") ON DELETE SET NULL
);

-- Add the supplier relationship to an existing Compras installation.
ALTER TABLE "compras" ADD COLUMN IF NOT EXISTS "marca_id" integer NULL;
ALTER TABLE "compras" ADD COLUMN IF NOT EXISTS "pago_efectivo_nio" numeric(12, 2) NOT NULL DEFAULT 0;
ALTER TABLE "compras" ADD COLUMN IF NOT EXISTS "pago_cuenta_nio" numeric(12, 2) NOT NULL DEFAULT 0;
DO $$
BEGIN
  ALTER TABLE "compras" ADD CONSTRAINT "fk_compras_marca"
    FOREIGN KEY ("marca_id") REFERENCES "marcas" ("id") ON DELETE SET NULL;
EXCEPTION WHEN duplicate_object THEN NULL;
END $$;

CREATE TABLE IF NOT EXISTS "compra_detalles" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "compra_id" integer NOT NULL,
  "producto_id" integer NOT NULL,
  "cantidad" integer NOT NULL CHECK ("cantidad" > 0),
  "costo_unitario_nio" numeric(12, 2) NOT NULL CHECK ("costo_unitario_nio" >= 0),
  "costo_envio_unitario_nio" numeric(12, 2) NOT NULL DEFAULT 0 CHECK ("costo_envio_unitario_nio" >= 0),
  "subtotal_nio" numeric(12, 2) NOT NULL CHECK ("subtotal_nio" >= 0),
  PRIMARY KEY ( "id" ),
  CONSTRAINT "fk_compra_detalles_compra" FOREIGN KEY ("compra_id") REFERENCES "compras" ("id") ON DELETE CASCADE,
  CONSTRAINT "fk_compra_detalles_producto" FOREIGN KEY ("producto_id") REFERENCES "productos" ("id")
);
CREATE INDEX IF NOT EXISTS "ix_compras_fecha_compra" ON "compras" ("fecha_compra");
CREATE INDEX IF NOT EXISTS "ix_compras_marca_id" ON "compras" ("marca_id");
CREATE INDEX IF NOT EXISTS "ix_compra_detalles_compra_id" ON "compra_detalles" ("compra_id");
CREATE INDEX IF NOT EXISTS "ix_compra_detalles_producto_id" ON "compra_detalles" ("producto_id");
-- Purchases are managed through the backend; keep them unavailable to direct Data API roles by default.
ALTER TABLE "compras" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "compra_detalles" ENABLE ROW LEVEL SECURITY;

-- Upgrade an existing Supabase database created from an earlier version of this schema.
-- Cost and suggested-price fields for perfume inventory (amounts in NIO).
ALTER TABLE "productos" ADD COLUMN IF NOT EXISTS "costo_nio" numeric NULL;
ALTER TABLE "productos" ADD COLUMN IF NOT EXISTS "costo_envio_nio" numeric(12, 2) NOT NULL DEFAULT 0;
ALTER TABLE "productos" ADD COLUMN IF NOT EXISTS "margen_utilidad_pct" numeric(7, 2) NOT NULL DEFAULT 30;
ALTER TABLE "productos" ADD COLUMN IF NOT EXISTS "costo_total_nio" numeric(12, 2) GENERATED ALWAYS AS (round(coalesce("costo_nio", 0) + "costo_envio_nio", 2)) STORED;
ALTER TABLE "productos" ADD COLUMN IF NOT EXISTS "precio_minimo_nio" numeric(12, 2) GENERATED ALWAYS AS (round(coalesce("costo_nio", 0) + "costo_envio_nio", 2)) STORED;
ALTER TABLE "productos" ADD COLUMN IF NOT EXISTS "utilidad_nio" numeric(12, 2) GENERATED ALWAYS AS (round((coalesce("costo_nio", 0) + "costo_envio_nio") * "margen_utilidad_pct" / 100, 2)) STORED;
ALTER TABLE "productos" ADD COLUMN IF NOT EXISTS "precio_sugerido_nio" numeric(12, 2) GENERATED ALWAYS AS (round((coalesce("costo_nio", 0) + "costo_envio_nio") * (1 + "margen_utilidad_pct" / 100), 2)) STORED;

CREATE TABLE "renta" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "marca_id" integer NULL,
  "fecha_pago" timestamp without time zone NULL,
  "monto" double precision NULL,
  CONSTRAINT "pk_renta" PRIMARY KEY ( "id" )
);

CREATE TABLE "renta_pago" (
  "pago_id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "renta_id" integer NULL,
  "monto_pagado" double precision NULL,
  "fecha_pago" timestamp without time zone NULL,
  "comentario" text NULL,
  CONSTRAINT "pk_renta_pago" PRIMARY KEY ( "pago_id" )
);

CREATE TABLE "retiros" (
  "id" integer NOT NULL,
  "marca_id" integer NOT NULL,
  "usuario_id" integer NOT NULL,
  "fecha_retiro" date NOT NULL,
  "motivo" text NOT NULL,
  "estado_id" integer NOT NULL,
  CONSTRAINT "pk__retiros__3213e83f8eb5b8ab" PRIMARY KEY ( "id" )
);

CREATE TABLE "usuarios" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "nombre" varchar(255) NOT NULL,
  "email" varchar(255) NOT NULL,
  "usuario" varchar(100) NOT NULL,
  "pass" varchar(255) NOT NULL,
  "rol" varchar(50) NOT NULL,
  "estado_id" integer NOT NULL,
  "creado_en" timestamp without time zone NULL,
  PRIMARY KEY ( "id" ),
  UNIQUE ( "usuario" ),
  UNIQUE ( "email" )
);
-- User records and password hashes are managed only by the trusted backend.
ALTER TABLE "usuarios" ENABLE ROW LEVEL SECURITY;

CREATE TABLE "venta_detalles" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "venta_id" integer NOT NULL,
  "producto_id" integer NOT NULL,
  "cantidad" integer NOT NULL,
  "precio_unitario" numeric(12, 2) NOT NULL,
  "descuento" numeric(12, 2) NOT NULL,
  "subtotal" numeric(12, 2) NOT NULL,
  PRIMARY KEY ( "id" )
);

CREATE TABLE "ventas" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "usuario_id" integer NULL,
  "cliente_id" bigint NOT NULL,
  "metodo_pago_id" bigint NOT NULL,
  "total" numeric(12, 2) NOT NULL,
  "comision_pos" numeric(12, 2) NOT NULL,
  "estado_id" integer NOT NULL,
  "fecha_venta" timestamp without time zone NULL,
  PRIMARY KEY ( "id" )
);

-- Keep physical stock separate from catalog product data. On upgrades, migrate
-- existing balances from purchase and sale history, then remove legacy columns.
ALTER TABLE "productos" ADD COLUMN IF NOT EXISTS "stock" integer NOT NULL DEFAULT 0;
ALTER TABLE "productos" ADD COLUMN IF NOT EXISTS "stock_critico" integer NOT NULL DEFAULT 5;
CREATE TABLE IF NOT EXISTS "inventario" (
  "producto_id" integer NOT NULL,
  "stock" integer NOT NULL DEFAULT 0 CHECK ("stock" >= 0),
  "stock_critico" integer NOT NULL DEFAULT 5 CHECK ("stock_critico" >= 0),
  PRIMARY KEY ("producto_id"),
  CONSTRAINT "fk_inventario_producto" FOREIGN KEY ("producto_id") REFERENCES "productos" ("id") ON DELETE CASCADE
);
INSERT INTO "inventario" ("producto_id", "stock", "stock_critico")
SELECT p."id",
       GREATEST(
         COALESCE((SELECT sum(cd."cantidad") FROM "compra_detalles" cd WHERE cd."producto_id" = p."id"), 0)
         - COALESCE((SELECT sum(vd."cantidad") FROM "venta_detalles" vd WHERE vd."producto_id" = p."id"), 0),
         0
       ),
       COALESCE(p."stock_critico", 5)
FROM "productos" p
ON CONFLICT ("producto_id") DO UPDATE SET "stock" = EXCLUDED."stock";
ALTER TABLE "productos" DROP COLUMN IF EXISTS "stock";
ALTER TABLE "productos" DROP COLUMN IF EXISTS "stock_critico";
ALTER TABLE "inventario" ENABLE ROW LEVEL SECURITY;
CREATE INDEX IF NOT EXISTS "ix_inventario_stock" ON "inventario" ("stock");

